package main

import (
	"encoding/json"
	"fmt"
	"strings"
	"time"
)

// FormatConsole prints results as a table to stdout.
func FormatConsole(results []ResolvedResult, missed []string) {
	fmt.Println()
	fmt.Println("=== nrx.league Offset Scanner ===")
	fmt.Println()

	// Header
	fmt.Printf("  %-30s | %-10s | %-28s | %-12s\n",
		"Pattern", "Match RVA", "Class", "Offset")
	fmt.Printf("  %s-+-%s-+-%s-+-%s\n",
		strings.Repeat("-", 30), strings.Repeat("-", 10),
		strings.Repeat("-", 28), strings.Repeat("-", 12))

	// Group by class
	var ripResults, structResults, funcResults, unknownResults []ResolvedResult
	for _, r := range results {
		switch r.Class {
		case ClassRIPRelative:
			ripResults = append(ripResults, r)
		case ClassStructOffset:
			structResults = append(structResults, r)
		case ClassFunctionEntry:
			funcResults = append(funcResults, r)
		default:
			unknownResults = append(unknownResults, r)
		}
	}

	printGroup := func(label string, group []ResolvedResult) {
		if len(group) == 0 {
			return
		}
		fmt.Printf("\n  --- %s ---\n", label)
		for _, r := range group {
			offsetStr := fmt.Sprintf("0x%X", r.ResolvedOffset)
			fmt.Printf("  %-30s | 0x%08X | %-28s | %-12s\n",
				r.Match.PatternName, r.Match.RVA, r.ClassLabel, offsetStr)
		}
	}

	printGroup("Global Pointers (RIP-relative)", ripResults)
	printGroup("Struct Member Offsets", structResults)
	printGroup("Function Entry Points", funcResults)
	printGroup("Unclassified", unknownResults)

	// Missed patterns
	if len(missed) > 0 {
		fmt.Printf("\n  --- NOT FOUND (%d) ---\n", len(missed))
		for _, name := range missed {
			fmt.Printf("  [MISS] %s\n", name)
		}
	}

	// Summary
	fmt.Printf("\n  Summary: %d/%d patterns matched\n\n",
		len(results), len(results)+len(missed))
}

// FormatHeader generates C++ code compatible with Offsets.h.
func FormatHeader(results []ResolvedResult) string {
	var sb strings.Builder

	sb.WriteString("#pragma once\n")
	sb.WriteString("#include <cstdint>\n\n")
	sb.WriteString(fmt.Sprintf("// Auto-generated by offsetscan on %s\n",
		time.Now().Format("2006-01-02")))
	sb.WriteString("namespace Offset\n{\n")

	// Group by class
	var ripResults, structResults, funcResults []ResolvedResult
	for _, r := range results {
		switch r.Class {
		case ClassRIPRelative:
			ripResults = append(ripResults, r)
		case ClassStructOffset:
			structResults = append(structResults, r)
		case ClassFunctionEntry:
			funcResults = append(funcResults, r)
		}
	}

	writeGroup := func(comment string, group []ResolvedResult) {
		if len(group) == 0 {
			return
		}
		sb.WriteString(fmt.Sprintf("\n    // --- %s ---\n", comment))
		for _, r := range group {
			sb.WriteString(fmt.Sprintf("    inline constexpr uint64_t %s = 0x%X;\n",
				r.Match.PatternName, r.ResolvedOffset))
		}
	}

	writeGroup("Global Pointers (RIP-relative resolved)", ripResults)
	writeGroup("Struct Member Offsets (displacement-extracted)", structResults)
	writeGroup("Function RVAs (entry point / call resolved)", funcResults)

	sb.WriteString("}\n")
	return sb.String()
}

// JSONResult is the JSON-serializable output format.
type JSONResult struct {
	Name           string `json:"name"`
	MatchRVA       string `json:"match_rva"`
	Class          string `json:"class"`
	ResolvedOffset string `json:"resolved_offset"`
	Displacement   int32  `json:"displacement"`
	DispBytes      string `json:"disp_bytes,omitempty"`
}

// FormatJSON returns the results as a JSON array.
func FormatJSON(results []ResolvedResult) string {
	var out []JSONResult
	for _, r := range results {
		dispHex := ""
		if len(r.DispBytes) > 0 {
			parts := make([]string, len(r.DispBytes))
			for i, b := range r.DispBytes {
				parts[i] = fmt.Sprintf("%02X", b)
			}
			dispHex = strings.Join(parts, " ")
		}
		out = append(out, JSONResult{
			Name:           r.Match.PatternName,
			MatchRVA:       fmt.Sprintf("0x%X", r.Match.RVA),
			Class:          r.ClassLabel,
			ResolvedOffset: fmt.Sprintf("0x%X", r.ResolvedOffset),
			Displacement:   r.Displacement,
			DispBytes:      dispHex,
		})
	}

	data, _ := json.MarshalIndent(out, "", "  ")
	return string(data)
}
